class BigObject { char data[1024 * 1024]; }; // 1MB object

void run_scenario() {
    std::weak_ptr<BigObject> weak_p;

    // Scenario 1: Using make_shared
    {
        auto shared_p = std::make_shared<BigObject>();
        weak_p = shared_p;
        // shared_p goes out of scope. Strong count is 0.
        // However, weak_p still exists. Weak count is 1.
        // The 1MB memory for BigObject REMAINS ALLOCATED here.
    }
    // Memory is freed only when weak_p is destroyed at the end of the function.

    // Scenario 2: Using new directly
    {
        std::shared_ptr<BigObject> shared_p(new BigObject());
        weak_p = shared_p;
        // shared_p goes out of scope. Strong count is 0.
        // The 1MB memory for BigObject IS DEALLOCATED here immediately.
        // Only the small control block's memory remains.
    }
    // The control block memory is freed when weak_p is destroyed.
}

// Exception-safety issue with direct new:
void process(std::shared_ptr<BigObject> p, int priority);
int compute_priority(); // This might throw an exception

void unsafe_call() {
    // Potentially leaky call. Order of evaluation is unspecified.
    // 1. new BigObject() could be evaluated.
    // 2. compute_priority() could be evaluated, and it might throw.
    // 3. std::shared_ptr constructor is called.
    // If 2 throws after 1, the memory from new is leaked.
    process(std::shared_ptr<BigObject>(new BigObject()), compute_priority());
}

void safe_call() {
    // Safe version: The smart pointer is fully constructed before being passed.
    std::shared_ptr<BigObject> p(new BigObject());
    process(p, compute_priority());
}
